```csharp
public static async Task UpdatePostTitleAsync(
    BlogContext context,
    int id,
    string title,
    CancellationToken cancellationToken)
{
    var postQuery =
        from post in context.Posts
        where post.Id == id
        select post;

    var post = await postQuery.FirstOrDefaultAsync(cancellationToken);

    if (post is null)
    {
        throw new InvalidOperationException($"Post with id {id} was not found.");
    }

    post.Title = title;
    await context.SaveChangesAsync(cancellationToken);
}
```

